     1	package rabinkarp;
     2	
     3	public final class PolynomialHashCalculator implements HashCalculator {
     4	    private final int radix;
     5	    private final int modulus;
     6	
     7	    public PolynomialHashCalculator(int radix, int modulus) {
     8	        this.radix = radix;
     9	        this.modulus = modulus;
    10	    }
    11	
    12	    @Override
    13	    public int hash(CharSequence seq, int length) {
    14	        int hash = 0;
    15	        for (int i = 0; i < length; i++) {
    16	            hash = (radix * hash + seq.charAt(i)) % modulus;
    17	        }
    18	        return hash;
    19	    }
    20	
    21	    @Override
    22	    public int highOrderFactor(int patternLength) {
    23	        int h = 1;
    24	        for (int i = 0; i < patternLength - 1; i++) {
    25	            h = (h * radix) % modulus;
    26	        }
    27	        return h;
    28	    }
    29	
    30	    @Override
    31	    public int roll(int currentHash, char leaving, char entering, int highOrderFactor) {
    32	        int hash = (radix * (currentHash - leaving * highOrderFactor) + entering) % modulus;
    33	        if (hash < 0) hash += modulus;
    34	        return hash;
    35	    }
    36	}

