    17	    @Override public String toString() { return text.subSequence(start, start + length).toString(); }
    18	
    19	    int start() { return start; }
    20	
    21	    /** First character of this window; leaves the window when it slides forward. */
    22	    char leaving() { return charAt(0); }
    23	
    24	    /** First character past this window; enters the window when it slides forward. */
    25	    char entering() { return text.charAt(start + length); }
    26	
    27	    TextWindow slide() { return new TextWindow(text, start + 1, length); }
